import { usersAPI } from "../api/api";
import { updateObjectInArray } from "../utils/object-helpers";
const FOLLOW = 'FOLLOW';
const UNFOLLOW = 'UNFOLLOW';
const SET_USERS = 'SET_USERS';
const SET_CURRENT_PAGE = 'SET_CURRENT_PAGE';
const SET_TOTAL_USERS_COUNT = 'SET_TOTAL_USERS_COUNT';
const TOGGLE_IS_FETCHING = 'TOGGLE_IS_FETCHING';
const TOGGLE_FOLLOWING_PROGRESS = 'TOGGLE_FOLLOWING_PROGRESS';



let initialState = {

    users: [
        // { id: 1, fullName: 'Dmitriy', followed: false, status: 'I am a boss', location: { city: 'Minsk', country: 'Belarus' }, photoUrl: 'https://cdn-icons-png.flaticon.com/512/149/149071.png' },
        // { id: 2, fullName: 'Vasya', followed: false, status: 'asdads', location: { city: 'Moscow', country: 'Belarus' }, photoUrl: 'https://cdn-icons-png.flaticon.com/512/149/149071.png' },
        // { id: 3, fullName: 'Sasha', followed: true, status: 'fffff', location: { city: 'Kyiv', country: 'Belarus' }, photoUrl: 'https://cdn-icons-png.flaticon.com/512/149/149071.png' },
        // { id: 4, fullName: 'Xuynyasha', followed: true, status: 'ping pong', location: { city: 'Hangzhou', country: 'Belarus' }, photoUrl: 'https://cdn-icons-png.flaticon.com/512/149/149071.png' },
    ],
    pageSize: 5,
    totalUsersCount: 0,
    currentPage: 1,
    isFetching: true,
    followingInProgress: []


};


const usersReducer = (state = initialState, action) => {

    switch (action.type) {
        case FOLLOW: {
            return {
                ...state,
                users: updateObjectInArray(state.users, action.userId, "id", { followed: true })
                
            };
        };
        case UNFOLLOW: {
            return {
                ...state,
                users: updateObjectInArray(state.users, action.userId, "id", { followed: false }) 
               
            };
        };
        case SET_USERS: {
            return { ...state, users: action.users };
        };
        case SET_CURRENT_PAGE: {
            return { ...state, currentPage: action.currentPage };
        };

        case SET_TOTAL_USERS_COUNT: {
            return { ...state, totalUsersCount: action.count };
        };
        case TOGGLE_IS_FETCHING: {
            return { ...state, isFetching: action.isFetching };
        };
        case TOGGLE_FOLLOWING_PROGRESS: {
            return {
                ...state,
                followingInProgress: action.isFetching
                    ? [...state.followingInProgress, action.userId]
                    : state.followingInProgress.filter(id => id != action.userId)
            };
        };
        default:
            return state;
    }

}

export const followSuccess = (userId) => ({ type: 'FOLLOW', userId });

export const unfollowSuccess = (userId) => ({ type: 'UNFOLLOW', userId });

export const setUsers = (users) => ({ type: 'SET_USERS', users });

export const setCurrentPage = (currentPage) => ({ type: 'SET_CURRENT_PAGE', currentPage });

export const setTotalUsersCount = (totalUsersCount) => ({ type: 'SET_TOTAL_USERS_COUNT', count: totalUsersCount });

export const toggleIsFetching = (isFetching) => ({ type: 'TOGGLE_IS_FETCHING', isFetching });

export const toggleFollowingProgress = (isFetching, userId) => ({ type: 'TOGGLE_FOLLOWING_PROGRESS', isFetching, userId });

export const requestUsers = (page, currentPage) => {
    return async (dispatch) => {
        dispatch(toggleIsFetching(true));
        let data = await usersAPI.getUsers(currentPage, page);

        dispatch(toggleIsFetching(false));
        dispatch(setCurrentPage(currentPage));
        dispatch(setUsers(data.items));
        dispatch(setTotalUsersCount(data.totalCount));

    }
};


const folloUnfollowFlow = async (dispatch, userId, apiMethod, actionCreator) => {
    dispatch(toggleFollowingProgress(true, userId));
        let response = await apiMethod(userId);

        if (response.data.resultCode === 0) {
            dispatch(actionCreator(userId));
        }
        dispatch(toggleFollowingProgress(false, userId));

}

export const follow = (userId) => {
    return async (dispatch) => {
        let apiMethod = usersAPI.follow.bind(usersAPI);
        let actionCreator = followSuccess;
        folloUnfollowFlow(dispatch, userId, apiMethod, actionCreator);

        

    }
}

export const unfollow = (userId) => {
    return async (dispatch) => {
        let apiMethod = usersAPI.unfollow.bind(usersAPI);
        let actionCreator = unfollowSuccess;
        folloUnfollowFlow(dispatch, userId, apiMethod, actionCreator);

    }
}



export default usersReducer;