import './App.css';
import Navbar from './components/Navbar/Navbar';

import { Routes, Route } from 'react-router-dom';
import News from './components/News/News';
import UsersContainer from './components/Users/UsersContainer';
// import ProfileContainer from './components/Profile/ProfileContainer';
import { useParams } from 'react-router-dom';
import HeaderContainer from './components/Header/HeaderContainer';
import Login from './components/Login/Login';
import React, { startTransition, Suspense } from 'react';
import { connect } from 'react-redux';
import { compose } from 'redux';
import { initializeApp } from './redux/app-reducer';
import Preloader from './components/common/Preloader/Preloader';
import { BrowserRouter } from 'react-router-dom';
import { Provider } from 'react-redux';
import store from './redux/redux-store';
import Profile from './components/Profile/Profile';
import { withSuspense } from './hoc/withSuspense';

// import DialogsContainer from './components/Dialogs/DialogsContainer';
const DialogsContainer = React.lazy(() => import('./components/Dialogs/DialogsContainer'));
const ProfileContainer = React.lazy(() => import('./components/Profile/ProfileContainer'));

// Wrapper component to pass `userId` to ProfileContainer
const ProfileContainerWrapper = () => {
  const params = useParams();
  console.log('Extracted userId:', params.userId); // Debugging
  return <ProfileContainer userId={params.userId} />;
};

class App extends React.Component {
  componentDidMount() {
    this.props.initializeApp();
  }
  render() {
    if (!this.props.initialized) {
      return <Preloader />
    }

    return (
      <div className='app-wrapper'>
        <HeaderContainer />
        <Navbar />
        <div className='app-wrapper-content'>
          <Routes>
            <Route path='/dialogs' element={withSuspense(DialogsContainer)()} />
            <Route path='/profile/:userId?' element={withSuspense(ProfileContainerWrapper)()} />
            <Route path='/news' element={<News />} />
            <Route path='/music' element={<div>Music</div>} />
            <Route path='/settings' element={<div>Settings</div>} />
            <Route exact path='/users' element={<UsersContainer />} />
            <Route path='/login' element={<Login />} />
          </Routes>
        </div>
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  initialized: state.app.initialized


});

let AppContainer = compose(
  connect(mapStateToProps, { initializeApp })(App));

const SamuraiJSApp = (props) => {
  return <BrowserRouter>
    <Provider store={store}>
      <AppContainer />
    </Provider>
  </BrowserRouter>
}



export default SamuraiJSApp;