import classes from './Post.module.css';
const Post = (props) => {
  return (
    <div className={classes.item}>
      <img src='https://habrastorage.org/r/w1560/getpro/habr/upload_files/e3a/645/bae/e3a645baee8555e02b5a2515e2667869.png' alt='avatar' />
      {props.message}
      <div>
        <span>like</span>
      </div>
    </div>
  );
}
export default Post;