import React from 'react';
import classes from './MyPosts.module.css';
import Post from './Post/Post';
import { reduxForm, Field } from 'redux-form';
import { maxLengthCreator, required } from '../../../utils/validators';
import { TextArea } from '../../common/FromsControls';

let maxLength50 = maxLengthCreator(50);

const MyPosts = React.memo((props) => {
  console.log('MyPosts rendering');
  const addNewPostText = (values) => {
    props.addPost(values.newPostText);
  };

  const postsElements = props.posts.map((p) => (
    <Post message={p.message} likesCount={p.likesCount} />
  ));

  return (
    <div>
      <h3>My posts</h3>
      <AddNewPostFormRedux onSubmit={addNewPostText} postsElements={postsElements} />
    </div>
  );
});

const AddNewPostForm = (props) => {
  return (
    <form onSubmit={props.handleSubmit}>
      <div>
        <Field
          type={'textarea'}
          name={'newPostText'}
          placeholder={'Post message'}
          component={TextArea}
          validate={[required, maxLength50]}
        />
      </div>
      <div>
        <button>Add post</button>
      </div>
      <div className={classes.posts}>{props.postsElements}</div>
    </form>
  );
};

const AddNewPostFormRedux = reduxForm({ form: 'ProfileAddNewPostForm' })(AddNewPostForm);

export default MyPosts;